use vstd::prelude::*;

verus! {

/// Given a 1D vector of f32, returns a 2D vector with exactly one row,
/// preserving the order and values of the input.
fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
    ensures
        // The outer vector has exactly one row
        result.len() == 1,
        // The single row has the same length as the input
        result[0].len() == arr.len(),
        // Element-wise equality between the input and the row
        forall |i: usize| i < arr.len() ==> result[0][i] == arr[i],
{
    let result: Vec<Vec<f32>> = vec![arr];
    result
}

} // end verus!

